/// Application-wide configuration loaded from TOML file or defaults.

#[derive(Debug, Clone)]
pub struct Config {
    pub ollama_host: String,
    pub ollama_port: u16,
    pub server_bind: String,
    pub server_port: u16,
    pub refresh_interval_secs: u64,
    pub gpu_device_index: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            ollama_host: "http://192.168.1.50".into(),
            ollama_port: 11434,
            server_bind: "0.0.0.0".into(),
            server_port: 3000,
            refresh_interval_secs: 15,
            gpu_device_index: 0,
        }
    }
}

impl Config {
    /// Load config from `config.toml` in the current directory, falling back to defaults for missing values.
    pub fn load() -> Self {
        let mut config = Self::default();

        if let Ok(contents) = std::fs::read_to_string("config.toml") {
            if let Ok(parsed): Result<ConfigRaw, _> = toml::from_str(&contents) {
                if let Some(ollama) = parsed.ollama {
                    config.ollama_host = ollama.host.unwrap_or(config.ollama_host);
                    config.ollama_port = ollama.port.unwrap_or(config.ollama_port);
                }
                if let Some(server) = parsed.server {
                    config.server_bind = server.bind.unwrap_or(config.server_bind);
                    config.server_port = server.port.unwrap_or(config.server_port);
                    config.refresh_interval_secs = server.refresh.unwrap_or(config.refresh_interval_secs);
                }
                if let Some(gpu) = parsed.gpu {
                    config.gpu_device_index = gpu.device.unwrap_or(config.gpu_device_index);
                }
            } else {
                tracing::warn!("Failed to parse config.toml, using defaults");
            }
        }

        config
    }

    pub fn ollama_base_url(&self) -> String {
        format!("{}:{}", self.ollama_host, self.ollama_port)
    }
}

// --- Raw TOML parsing structures ---

struct ConfigRaw {
    ollama: Option<OllamaSection>,
    server: Option<ServerSection>,
    gpu: Option<GpuSection>,
}

struct OllamaSection {
    host: Option<String>,
    port: Option<u16>,
}

struct ServerSection {
    bind: Option<String>,
    port: Option<u16>,
    refresh: Option<u64>,
}

struct GpuSection {
    device: Option<usize>,
}

/// Shared data types for Ollama and GPU state.

use serde::{Deserialize, Serialize};

// ── Ollama API response types ───────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaTagsResponse {
    pub models: Vec<OllamaModelEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OllamaModelEntry {
    #[serde(rename = "name")]
    pub model_name: String,
    #[serde(rename = "size")]
    pub size_bytes: Option<u64>,
    #[serde(rename = "digest")]
    pub digest: Option<String>,
    #[serde(rename = "modified_at")]
    pub modified_at: Option<String>,
}

// ── Aggregated status (exposed by REST API) ─────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct MonitorStatus {
    pub ollama_url: String,
    pub ollama_reachable: bool,
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub gpu: GpuMetric,
    pub timestamp: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct GpuMetric {
    pub name: Option<String>,
    pub temperature_c: Option<f64>,
    pub memory_used_mib: Option<u64>,
    pub memory_total_mib: Option<u64>,
    pub memory_remaining_mib: Option<u64>,
    pub utilization_pct: Option<f64>,
    pub power_watts: Option<f64>,
}

impl GpuMetric {
    pub fn placeholder() -> Self {
        Self {
            name: None,
            temperature_c: None,
            memory_used_mib: None,
            memory_total_mib: None,
            memory_remaining_mib: None,
            utilization_pct: None,
            power_watts: None,
        }
    }
}

// ── Web API response types (subset views) ──────────────────────

#[derive(Debug, Clone, Serialize)]
pub struct ApiModelResponse {
    pub loaded_model: Option<String>,
    pub available_models: Vec<String>,
    pub total_count: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct ApiGpuResponse {
    pub gpu: GpuMetric,
    pub timestamp: String,
}

/// Client for the Ollama REST API.

use anyhow::{Context, Result};
use reqwest::Client;
use std::time::Duration;
use tracing::{debug, warn};

use crate::models::OllamaTagsResponse;

pub struct OllamaClient {
    base_url: String,
    http: Client,
}

impl OllamaClient {
    pub fn new(base_url: impl Into<String>) -> Self {
        Self {
            base_url: base_url.into(),
            http: Client::builder()
                .timeout(Duration::from_secs(10))
                .build()
                .expect("reqwest client build"),
        }
    }

    /// Fetch available models from `/api/tags`.
    pub async fn fetch_models(&self) -> Result<OllamaTagsResponse> {
        debug!("Fetching models from {}", self.base_url);
        let url = format!("{}/api/tags", self.base_url);

        Ok(self
            .http
            .get(&url)
            .send()
            .await
            .with_context(|| format!("Failed to connect to Ollama at {}", url))?
            .json::<OllamaTagsResponse>()
            .await
            .with_context(|| "Failed to parse Ollama /api/tags response")?)
    }

    /// Best-effort fetch; returns None on failure instead of propagating errors.
    pub async fn try_fetch_models(&self) -> Option<OllamaTagsResponse> {
        match self.fetch_models().await {
            Ok(resp) => Some(resp),
            Err(e) => {
                warn!("Ollama connection failed: {}", e);
                None
            }
        }
    }

    pub fn base_url(&self) -> &str {
        &self.base_url
    }
}

/// Parses `nvidia-smi` output to extract GPU metrics.

use anyhow::{Context, Result};
use std::process::Command;
use tracing::{debug, warn};

use crate::models::GpuMetric;

/// Query structured GPU data via nvidia-smi CSV mode (no header).
pub fn query_gpu(device_index: usize) -> Result<GpuMetric> {
    let output = Command::new("nvidia-smi")
        .args(&[
            "--query-gpu=index,name,temperature.gpu,memory.used,memory.total,utilization.gpu,power.draw",
            "--format=csv,noheader,nounits",
            "--id",
            &device_index.to_string(),
        ])
        .output()
        .context("Failed to execute nvidia-smi (is it installed?). Using placeholder GPU metrics.")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("nvidia-smi failed: {}", stderr.trim());
    }

    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    debug!("nvidia-smi raw output: {}", stdout);

    parse_gpu_csv_line(&stdout, device_index)
}

/// Best-effort GPU query — returns a placeholder metric on failure.
pub fn try_query_gpu(device_index: usize) -> GpuMetric {
    match query_gpu(device_index) {
        Ok(metric) => metric,
        Err(e) => {
            warn!("GPU query failed (this is expected in non-GPU dev environments): {}", e);
            GpuMetric::placeholder()
        }
    }
}

/// Parse a single CSV line from `nvidia-smi --query-... --format=csv,noheader,nounits`.
/// Expected columns: index, name, temp, mem_used, mem_total, util_gpu, power_draw
fn parse_gpu_csv_line(line: &str, expected_index: usize) -> Result<GpuMetric> {
    // nvidia-smi output has fields separated by ", ". GPU name can contain commas
    // but since we query a specific device by --id, there is exactly one line.
    // We split from the right for numeric fields and treat the middle as name.

    let parts: Vec<&str> = line.split(", ").collect();

    if parts.len() < 7 {
        anyhow::bail!("Unexpected nvidia-smi CSV fields count: {}", parts.len());
    }

    // Parse from right for numeric fields, name is everything between index and temperature.
    let power = parse_optional_f64(parts.last().copied());
    let utilization = parse_optional_f64(parts.get(parts.len() - 2));
    let mem_total_raw = parts.get(parts.len() - 3);
    let mem_used_raw = parts.get(parts.len() - 4);
    let temp = parse_optional_f64(parts.get(parts.len() - 5));

    // Name is in the middle (from index 1 to len-6)
    let name_fields: Vec<_> = parts[1..parts.len() - 6].iter().map(|s| *s).collect();
    let name = if !name_fields.is_empty() {
        Some(name_fields.join(", "))
    } else {
        None
    };

    let idx_parsed = parts.first().and_then(|s| s.trim().parse::<usize>().ok());
    if Some(expected_index) != idx_parsed {
        anyhow::bail!(
            "GPU index mismatch: expected {}, got {:?}",
            expected_index,
            idx_parsed
        );
    }

    let mem_used = parse_optional_u64(mem_used_raw);
    let mem_total = parse_optional_u64(mem_total_raw);

    let remaining = match (mem_used, mem_total) {
        (Some(u), Some(t)) => Some(t.saturating_sub(u)),
        _ => None,
    };

    Ok(GpuMetric {
        name,
        temperature_c: temp,
        memory_used_mib: mem_used,
        memory_total_mib: mem_total,
        memory_remaining_mib: remaining,
        utilization_pct: utilization,
        power_watts: power,
    })
}

fn parse_optional_f64(s: Option<&str>) -> Option<f64> {
    s.and_then(|v| v.trim().parse::<f64>().ok())
}

fn parse_optional_u64(s: Option<&str>) -> Option<u64> {
    s.and_then(|v| v.trim().parse::<u64>().ok())
}

/// Axum REST API server + embedded web dashboard.

use anyhow::Result;
use axum::{
    extract::State,
    http::StatusCode,
    response::Html,
    routing::get,
    Router,
};
use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};
use tokio::sync::RwLock;
use tracing::info;

use crate::config::Config;
use crate::models::{ApiGpuResponse, ApiModelResponse, MonitorStatus};
use crate::ollama::OllamaClient;
use crate::gpu::try_query_gpu;

// ── Application State ──────────────────────────────────────────

pub struct AppState {
    latest_status: Arc<RwLock<Option<MonitorStatus>>>,
}

impl AppState {
    pub fn new() -> Self {
        Self {
            latest_status: Arc::new(RwLock::new(None)),
        }
        }
    }

// ── Background refresh loop ─────────────────────────────────────

pub async fn run_refresh_loop(
    config: &Config,
    state: AppState,
) {
    let client = OllamaClient::new(config.ollama_base_url());
    let interval = Duration::from_secs(config.refresh_interval_secs);

    loop {
        // Query Ollama
        let tags_resp = client.try_fetch_models().await;
        let available: Vec<String> = match &tags_resp {
            Some(tags) => tags.models.iter().map(|m| m.model_name.clone()).collect(),
            None => vec![],
        };

        // Currently loaded model: Ollama doesn't have a direct "what's loaded" endpoint,
        // but we can infer it — the model that is most recently loaded tends to be at
        // the top of /api/tags. For now report None unless Ollama adds such an endpoint.
        // This is a known limitation; future enhancement: parse Ollama logs or use
        // experimental /api/ps endpoint if available.
        let loaded_model = match &tags_resp {
            Some(tags) => tags.models.first().map(|m| m.model_name.clone()),
            None => None,
        };

        // Query GPU
        let gpu_metric = try_query_gpu(config.gpu_device_index);

        let status = MonitorStatus {
            ollama_url: config.ollama_base_url(),
            ollama_reachable: tags_resp.is_some(),
            loaded_model,
            available_models: available.clone(),
            gpu: gpu_metric,
            timestamp: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
        };

        {
            let mut latest = state.latest_status.write().await;
            *latest = Some(status);
        }
    }
}

// ── HTTP Handlers ───────────────────────────────────────────────

async fn handle_dashboard(State(state): State<AppState>) -> Html<String> {
    Html(DASHBOARD_HTML.to_string())
}

async fn handle_api_status(
    State(state): State<AppState>,
) -> Result<axum::Json<MonitorStatus>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(s.clone())),
        None => Err((StatusCode::SERVICE_UNAVAILABLE, "First refresh not yet complete".into())),
    }
}

async fn handle_api_gpu(
    State(state): State<AppState>,
) -> Result<axum::Json<ApiGpuResponse>, (StatusCode, String)> {
    use crate::models::ApiGpuResponse;
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(ApiGpuResponse {
            gpu: s.gpu.clone(),
            timestamp: s.timestamp.clone(),
        })),
        None => Err((StatusCode::SERVICE_UNAVAILABLE, "First refresh not yet complete".into())),
    }
}

async fn handle_api_models(
    State(state): State<AppState>,
) -> Result<axum::Json<ApiModelResponse>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
    match latest.as_ref() {
        Some(s) => Ok(axum::Json(ApiModelResponse {
            loaded_model: s.loaded_model.clone(),
            available_models: s.available_models.clone(),
            total_count: s.available_models.len(),
        })),
        None => Err((StatusCode::SERVICE_UNAVAILABLE, "First refresh not yet complete".into())),
    }
}

// ── Builder ─────────────────────────────────────────────────────

pub async fn build_router(state: AppState) -> Router {
    Router::new()
        .route("/", get(handle_dashboard))
        .route("/api/status", get(handle_api_status))
        .route("/api/gpu", get(handle_api_gpu))
        .route("/api/models", get(handle_api_models))
        .with_state(state)
}

pub fn build_app(state: AppState, config: &Config) -> Result<SocketAddr> {
    let addr = SocketAddr::new(
        config.server_bind.parse().expect("invalid bind address"),
        config.server_port,
    );
    info!("Server will bind to {}", addr);
    Ok(addr)
}

