/// Axum REST API server + embedded web dashboard.

use anyhow::Result;
use axum::{
    extract::State,
    http::StatusCode,
    response::Html,
    routing::get,
    Router,
};
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, SystemTime},
};
use tokio::sync::RwLock;
use tracing::info as log_info;

use crate::config::Config;
use crate::models::{ApiGpuResponse, ApiModelResponse, MonitorStatus};
use crate::ollama::OllamaClient;
use crate::gpu::try_query_gpu;

/// Format current time as a readable timestamp string.
fn now_ts() -> String {
    let t = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map_or_else(|_| String::from("unknown"), |d| {
            let secs = d.as_secs();
            // Simple ISO-like format without chrono dependency
            let days = secs / 86400;
            let rem = secs % 86400;
            let h = rem / 3600;
            let m = (rem % 3600) / 60;
            let s = rem % 60;
            format!("epoch+{}d {:02}:{:02}:{:02} UTC", days, h, m, s)
        });
    t
}

// ── Application State ──────────────────────────────────────────

pub struct AppState {
    latest_status: Arc<RwLock<Option<MonitorStatus>>>,
}

impl AppState {
    pub fn new() -> Self {
        Self {
            latest_status: Arc::new(RwLock::new(None)),
        }
    }
}

// ── Background refresh loop ─────────────────────────────────────

pub async fn run_refresh_loop(
    config: &Config,
    state: AppState,
) {
    let client = OllamaClient::new(config.ollama_base_url());
    let interval = Duration::from_secs(config.refresh_interval_secs);

    loop {
        tokio::time::sleep(interval).await;

        // Query Ollama
        let tags_resp = client.try_fetch_models().await;
        let available: Vec<String> = match &tags_resp {
            Some(tags) => tags.models.iter().map(|m| m.model_name.clone()).collect(),
            None => vec![],
        };

        // Currently loaded model: Ollama doesn't have a direct "what's loaded" endpoint.
        // The model that appears first in /api/tags is the most recently interacted with.
        // Future enhancement: parse Ollama server logs or use /api/ps if added upstream.
        let loaded_model = match &tags_resp {
            Some(tags) => tags.models.first().map(|m| m.model_name.clone()),
            None => None,
        };

        // Query GPU
        let gpu_metric = try_query_gpu(config.gpu_device_index);

        let status = MonitorStatus {
            ollama_url: config.ollama_base_url(),
            ollama_reachable: tags_resp.is_some(),
            loaded_model,
            available_models: available.clone(),
            gpu: gpu_metric,
            timestamp: now_ts(),
        };

        {
            let mut latest = state.latest_status.write().await;
            *latest = Some(status);
        }
    }
}

// ── HTTP Handlers ───────────────────────────────────────────────

async fn handle_dashboard(_state: State<AppState>) -> Html<String> {
    Html(DASHBOARD_HTML.to_string())
}

async fn handle_api_status(
    state: State<AppState>,
) -> Result<axum::Json<MonitorStatus>, (StatusCode, String)> {
    let latest = state.latest_status.read().await;
