/// Ollama Monitor — main entry point.

mod api;
mod config;
mod gpu;
mod models;
mod ollama;

use anyhow::Result;
use tracing_subscriber::{fmt, EnvFilter};

#[tokio::main]
async fn main() -> Result<()> {
    // Initialise logging
    let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    fmt::Subscriber::builder()
        .with_env_filter(env_filter)
        .init();

    // Load configuration
    let config = config::Config::load();
    tracing::info!(
        config = ?config,
        "Configuration loaded"
    );

    // Shared application state
    let state = api::AppState::new();

    // Start background refresh loop
    let cfg_clone = config.clone();
    let state_clone = state.clone();
    tokio::spawn(async move {
        api::run_refresh_loop(&cfg_clone, state_clone).await;
    });

    // Build and start HTTP server
    let addr = api::build_listen_addr(&config)?;
    let app = api::build_router(state).await;

    tracing::info!("Starting Ollama Monitor on {}", addr);
    axum::Server::bind(&addr)
        .serve(app.into_make_service())
        .await
        .map_err(Into::into)
}

/// Clone impl needed for AppState (Arc-wrapped, so cheap).
impl Clone for api::AppState {
    fn clone(&self) -> Self {
        Self {
            latest_status: self.latest_status.clone(),
        }
    }
}

